input.command:
$ErrorActionPreference='Stop'
$root=(Get-Location).Path
$mc=Join-Path $root '.mutation-checks'
$ev=Join-Path $mc 'evidence'
$files=@('cache.go','cleanup.go','cache_test.go','cleanup_test.go','go.mod')
$dirs=[ordered]@{
  'delivery'=(Join-Path $mc 'delivery')
  'defect-1-missed-expiry'=(Join-Path $mc 'defect-1-missed-expiry')
  'defect-2-nonpositive-keeps-old'=(Join-Path $mc 'defect-2-nonpositive-keeps-old')
  'defect-3-cleanup-deletes-valid'=(Join-Path $mc 'defect-3-cleanup-deletes-valid')
}
$lines=@()
$lines += '# SHA256 comparison: root delivery vs .mutation-checks copies'
$lines += "# root: $root"
$lines += ''
$header = '{0,-16} {1,-8} {2,-8} {3,-8} {4,-8} {5}' -f 'file','delivery','defect1','defect2','defect3','root_sha256'
$lines += $header
$lines += ('-' * ($header.Length))
foreach($f in $files){
  $rh=(Get-FileHash (Join-Path $root $f) -Algorithm SHA256).Hash
  $statuses=@()
  foreach($k in $dirs.Keys){
    $ch=(Get-FileHash (Join-Path $dirs[$k] $f) -Algorithm SHA256).Hash
    $statuses += (if($ch -eq $rh){'MATCH'}else{'DIFF'})
  }
  $lines += ('{0,-16} {1,-8} {2,-8} {3,-8} {4,-8} {5}' -f $f,$statuses[0],$statuses[1],$statuses[2],$statuses[3],$rh)
}
$lines += ''
$lines += '# Expected differences only:'
$lines += '# delivery: all MATCH'
$lines += '# defect-1-missed-expiry: cache.go DIFF, all others MATCH'
$lines += '# defect-2-nonpositive-keeps-old: cache.go DIFF, all others MATCH'
$lines += '# defect-3-cleanup-deletes-valid: cleanup.go DIFF, all others MATCH'
Set-Content -Path (Join-Path $ev '08-hashes.txt') -Value ($lines -join "`n")

# hard assertions
foreach($f in $files){
  if((Get-FileHash (Join-Path $dirs['delivery'] $f) -Algorithm SHA256).Hash -ne (Get-FileHash (Join-Path $root $f) -Algorithm SHA256).Hash){ throw "delivery mismatch: $f" }
}
foreach($f in $files){
  $rh=(Get-FileHash (Join-Path $root $f) -Algorithm SHA256).Hash
  $h1=(Get-FileHash (Join-Path $dirs['defect-1-missed-expiry'] $f) -Algorithm SHA256).Hash
  $h2=(Get-FileHash (Join-Path $dirs['defect-2-nonpositive-keeps-old'] $f) -Algorithm SHA256).Hash
  $h3=(Get-FileHash (Join-Path $dirs['defect-3-cleanup-deletes-valid'] $f) -Algorithm SHA256).Hash
  if($f -eq 'cache.go'){
    if($h1 -eq $rh -or $h2 -eq $rh){ throw 'cache.go expected mutation missing' }
    if($h3 -ne $rh){ throw 'defect-3 unexpectedly changed cache.go' }
  } elseif($f -eq 'cleanup.go'){
    if($h3 -eq $rh){ throw 'cleanup.go expected mutation missing' }
    if($h1 -ne $rh -or $h2 -ne $rh){ throw 'defect-1/2 unexpectedly changed cleanup.go' }
  } else {
    if($h1 -ne $rh -or $h2 -ne $rh -or $h3 -ne $rh){ throw "unexpected mutation: $f" }
  }
}
Get-Content (Join-Path $ev '08-hashes.txt')
'HASH_ASSERTIONS=OK'

